import java.util.*;

public class E {
    static final int MAX = 1000000000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n > m) {
            int temp = n;
            n = m;
            m = temp;
        }

        int size = 1 << n;
        int[][] dp = new int[size][size];
        for (int[] row : dp) {
            Arrays.fill(row, MAX);
        }
        Arrays.fill(dp[0], 0);

        for (int step = 0; step < m; step++) {
            int[][] newDp = new int[size][size];
            for (int[] row : newDp) {
                Arrays.fill(row, MAX);
            }
            for (int prevMask = 0; prevMask < size; prevMask++) {
                for (int currMask = 0; currMask < size; currMask++) {
                    if (dp[prevMask][currMask] != MAX) {
                        int limit = (step == m - 1) ? 1 : size;
                        for (int nextMask = 0; nextMask < limit; nextMask++) {
                            int covered = 0;
                            for (int bit = 0; bit < n; bit++) {
                                if (((1 << bit) & currMask) == 0) {
                                    int above = bit - 1;
                                    int below = bit + 1;
                                    if (above >= 0 && ((1 << above) & currMask) != 0)
                                        covered |= 1 << bit;
                                    if (below < n && ((1 << below) & currMask) != 0)
                                        covered |= 1 << bit;
                                    if (((1 << bit) & prevMask) != 0)
                                        covered |= 1 << bit;
                                    if (((1 << bit) & nextMask) != 0)
                                        covered |= 1 << bit;
                                }
                            }
                            int cost = dp[prevMask][currMask] + n - Integer.bitCount(covered);
                            if (cost < newDp[currMask][nextMask]) {
                                newDp[currMask][nextMask] = cost;
                            }
                        }
                    }
                }
            }
            dp = newDp;
        }

        int minRes = MAX;
        for (int[] row : dp) {
            for (int val : row) {
                if (val < minRes) {
                    minRes = val;
                }
            }
        }
        System.out.println(n * m - minRes);
    }
}
