import sys

MAX = 1000000000

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    if n > m:
        n, m = m, n

    size = 1 << n
    dp = [[MAX for _ in range(size)] for _ in range(size)]
    for row in dp:
        row[0] = 0

    for step in range(m):
        newDp = [[MAX for _ in range(size)] for _ in range(size)]
        for prevMask in range(size):
            for currMask in range(size):
                if dp[prevMask][currMask] != MAX:
                    limit = 1 if step == m - 1 else size
                    for nextMask in range(limit):
                        covered = 0
                        for bit in range(n):
                            if ((1 << bit) & currMask) == 0:
                                above = bit - 1
                                below = bit + 1
                                if above >= 0 and ((1 << above) & currMask) != 0:
                                    covered |= 1 << bit
                                if below < n and ((1 << below) & currMask) != 0:
                                    covered |= 1 << bit
                                if ((1 << bit) & prevMask) != 0:
                                    covered |= 1 << bit
                                if ((1 << bit) & nextMask) != 0:
                                    covered |= 1 << bit
                        cost = dp[prevMask][currMask] + n - bin(covered).count('1')
                        if cost < newDp[currMask][nextMask]:
                            newDp[currMask][nextMask] = cost
        dp = newDp

    minRes = MAX
    for row in dp:
        for val in row:
            if val < minRes:
                minRes = val
    print(n * m - minRes)

